'use strict';
const outfitTypes={cape:'Cape',elytra:'Wings',wings:'Animated Wings',hat:'Hat',trinket:'Trinket',dress:'Dress'};
let outfitState={slots:{},share:false,showOthers:true},adminLibrary=[];
function glassValues(){return {clarity:Number($('glass-clarity').value),light:Number($('glass-light').value),quality:$('glass-quality').value,pointer:$('glass-pointer').checked,motion:$('glass-motion').checked};}
function applyGlassAppearance(value=state.settings.glass||{}){const g={clarity:1,light:.65,quality:'balanced',pointer:true,motion:true,...value};for(const [name,v]of Object.entries(g))document.body.dataset['glass'+name[0].toUpperCase()+name.slice(1)]=typeof v==='boolean'?(v?'on':'off'):v;document.body.style.setProperty('--glass-user-light',g.light);}
function fillGlassSettings(){const g={clarity:1,light:.65,quality:'balanced',pointer:true,motion:true,...state.settings.glass};for(const key of ['clarity','light','quality'])$('glass-'+key).value=g[key];for(const key of ['pointer','motion'])$('glass-'+key).checked=g[key];updateGlassLabels();applyGlassAppearance(g);}
function updateGlassLabels(){$('glass-clarity-value').value=Math.round(Number($('glass-clarity').value)*100)+'%';$('glass-light-value').value=Math.round(Number($('glass-light').value)*100)+'%';}
for(const key of ['clarity','light','quality','pointer','motion'])$('glass-'+key).addEventListener(['clarity','light'].includes(key)?'input':'change',()=>{updateGlassLabels();applyGlassAppearance(glassValues());});
$('glass-reset').addEventListener('click',()=>{state.settings.glass={clarity:1,light:.65,quality:'balanced',pointer:true,motion:true};fillGlassSettings();toast('Glass defaults restored. Save settings to keep them.');});
$('new-vanilla').addEventListener('click',()=>action(async()=>{$('create-loader').value='vanilla';await openCreate();}));
$('create-version-category').addEventListener('change',()=>action(async()=>{$('create-version-category').dataset.chosen='true';fillMinecraftVersions();await loadBuilds();}));
async function loadVanillaInstances(){const list=await api('vanilla-list');$('vanilla-grid').innerHTML=list.map(p=>'<article class="content-card vanilla-card"><span class="sponsor-badge">VANILLA · OFFICIAL FILES</span><span class="ready-version">'+escape(p.minecraft)+'</span><h3>'+escape(p.name)+'</h3><p>Separate worlds and settings. No mod loader or client mods.</p><button class="button subtle" data-vanilla="'+escape(p.id)+'" data-mutation '+(!p.available?'disabled':'')+'>Install vanilla</button></article>').join('');$('vanilla-grid').querySelectorAll('[data-vanilla]').forEach(button=>button.addEventListener('click',()=>action(async()=>{const r=await api('vanilla-install',{id:button.dataset.vanilla});selectedId=r.instance.id;await refresh();toast('Vanilla '+r.instance.minecraft+' installed.');})));}
function requireOutfit(){if(!selected())throw new Error('Select an instance first.');return {instanceId:selectedId,username:$('cosmetic-username').value.trim()||state.settings.offlineName,model:$('skin-model').value};}
async function loadOutfit(){if(!selected()){outfitState={slots:{},share:false,showOthers:true};}else outfitState=await api('wardrobe-settings',{instanceId:selectedId});$('outfit-slots').innerHTML=Object.entries(outfitTypes).map(([slot,type])=>'<label>'+escape(slot==='elytra'?'Elytra texture':slot==='wings'?'Animated wings':type)+'<select data-outfit-slot="'+slot+'"><option value="">Original provider</option>'+cosmeticCatalog.filter(p=>p.type===type&&(!p.voucherOnly||claimedCosmetics.includes(p.id))).map(p=>'<option value="'+escape(p.id)+'" '+(outfitState.slots[slot]===p.id?'selected':'')+'>'+escape(p.name)+'</option>').join('')+'</select><button type="button" class="text-button" data-outfit-preview="'+slot+'">Preview choice</button></label>').join('');$('outfit-share').checked=outfitState.share;$('outfit-show-others').checked=outfitState.showOthers;$('outfit-slots').querySelectorAll('[data-outfit-preview]').forEach(button=>button.addEventListener('click',()=>{const id=$('outfit-slots').querySelector('[data-outfit-slot="'+button.dataset.outfitPreview+'"]').value;if(id)selectCosmetic(id);}));}
$('outfit-apply').addEventListener('click',()=>action(async()=>{const p=requireOutfit(),slots=Object.fromEntries([...document.querySelectorAll('[data-outfit-slot]')].map(el=>[el.dataset.outfitSlot,el.value]));for(const [slot,id]of Object.entries(slots)){if(!id){await api('wardrobe-configure',{instanceId:p.instanceId,clearSlot:slot});continue;}if(!claimedCosmetics.includes(id))claimedCosmetics=await api('wardrobe-claim',{id});await api('wardrobe-equip',{...p,id});}await loadOutfit();toast('Outfit saved. Restart Minecraft; F9 changes slots while playing.');}));
for(const [id,key]of [['outfit-share','shareCosmetics'],['outfit-show-others','showOthers']])$(id).addEventListener('change',()=>action(async()=>{try{const p=requireOutfit();outfitState=await api('wardrobe-configure',{instanceId:p.instanceId,[key]:$(id).checked});$('outfit-status').textContent='Saved. Restart Minecraft or change sharing in the F9 Tweaks menu. The server and receiving clients need CPM.';}catch(error){$(id).checked=id==='outfit-share'?outfitState.share:outfitState.showOthers;throw error;}}));
$('outfit-sharing-install').addEventListener('click',()=>action(async()=>{await api('sharing-install',{...requireOutfit(),share:$('outfit-share').checked});toast('Shared wardrobe installed. Enable sharing, then join a CPM-enabled server.');await loadOutfit();}));
$('outfit-server-download').addEventListener('click',()=>action(async()=>{const r=await api('sharing-server',requireOutfit());if(r)toast('CPM server mod saved. Install it on a matching Fabric server.');}));
$('outfit-export').addEventListener('click',()=>action(async()=>{const r=await api('wardrobe-export-skin',requireOutfit());if(r)toast(r.instructions);}));
$('outfit-starter').addEventListener('click',()=>action(async()=>{if(!window.confirm('Replace the local skin with the free Studio starter skin? Your previous skin remains restorable.'))return;await api('skin-starter',requireOutfit());$('skin-preview-source').value='equipped';await loadPlayerSkin();toast('Free starter skin equipped. You can now choose hats, trinkets and dresses.');}));
async function refreshAdminLibrary(){if(!cloudAccount?.admin){$('admin-library').innerHTML=empty('Owner access required.','Sign in with the enrolled Admin account.');return;}adminLibrary=await api('admin-items');drawAdminLibrary();}
function drawAdminLibrary(){const query=$('admin-library-search').value.toLowerCase();$('admin-library').innerHTML=adminLibrary.map((record,index)=>({record,index})).filter(({record:r})=>!query||(r.item.name+' '+r.item.id+' '+r.kind).toLowerCase().includes(query)).map(({record:r,index})=>'<article class="admin-record"><div><strong>'+escape(r.item.name)+'</strong><small>'+escape(r.kind+' · '+r.item.id)+'</small></div><button type="button" class="button tiny" data-admin-edit="'+index+'">Edit</button><button type="button" class="button tiny danger" data-admin-delete="'+index+'">Unpublish</button></article>').join('')||empty('Nothing published yet.','Create a featured item or cosmetic below.');$('admin-library').querySelectorAll('[data-admin-edit]').forEach(button=>button.addEventListener('click',()=>editAdminRecord(adminLibrary[Number(button.dataset.adminEdit)])));$('admin-library').querySelectorAll('[data-admin-delete]').forEach(button=>button.addEventListener('click',()=>action(async()=>{const r=adminLibrary[Number(button.dataset.adminDelete)];if(!window.confirm('Unpublish '+r.item.name+' from '+r.kind+'?'))return;await api('admin-delete',{kind:r.kind,id:r.item.id});await refreshAdminLibrary();toast('Item unpublished.');})));}
function adminDraft(){return {kind:$('admin-kind').value,id:$('admin-id').value,name:$('admin-name').value,description:$('admin-description').value,address:$('admin-address').value,version:$('admin-version').value,provider:$('admin-provider').value,type:$('admin-type').value,projectId:$('admin-project-id').value,cosmeticType:$('admin-cosmetic-type').value,voucherOnly:$('admin-voucher-only').checked,texture:$('admin-pixels').toDataURL('image/png').split(',')[1]};}
function editAdminRecord({kind,item}){$('admin-kind').value=kind;for(const key of ['id','name','description','address','version','provider','projectId']){const field=$(key==='projectId'?'admin-project-id':'admin-'+key);if(field)field.value=item[key]||'';}if(kind==='featured')$('admin-type').value=item.type;if(kind==='cosmetics'){$('admin-cosmetic-type').value=item.type;$('admin-voucher-only').checked=!!item.voucherOnly;if(item.texture){const image=new Image();image.onload=()=>{const c=$('admin-pixels');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);};image.src='data:image/png;base64,'+item.texture;}}adminFields();$('admin-editor-note').textContent='Editing '+(item.name||'saved draft')+'. Publishing uses this record ID.';$('admin-form').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
$('admin-library-refresh').addEventListener('click',()=>action(refreshAdminLibrary));$('admin-library-search').addEventListener('input',drawAdminLibrary);
$('admin-draft-save').addEventListener('click',()=>action(async()=>{await api('admin-draft-save',adminDraft());$('admin-editor-note').textContent='Draft saved securely on this PC.';}));
$('admin-draft-load').addEventListener('click',()=>action(async()=>{const draft=await api('admin-draft-load');if(!draft)throw new Error('No draft saved on this PC.');editAdminRecord({kind:draft.kind,item:{...draft,type:draft.kind==='cosmetics'?draft.cosmeticType:draft.type}});}));
$('admin-new-item').addEventListener('click',()=>{$('admin-form').reset();resetPixelDesign();adminFields();$('admin-editor-note').textContent='New free item. Choose a unique record ID.';});
const pixelUndo=[],pixelRedo=[];let strokeStart;
const pixelSnapshot=()=>{const c=$('admin-pixels');return {width:c.width,height:c.height,data:c.getContext('2d').getImageData(0,0,c.width,c.height)};};
$('admin-pixels').addEventListener('pointerdown',()=>strokeStart=pixelSnapshot(),true);$('admin-pixels').addEventListener('pointerup',()=>{if(strokeStart){pixelUndo.push(strokeStart);if(pixelUndo.length>30)pixelUndo.shift();pixelRedo.length=0;strokeStart=null;}});
function restorePixels(image){const c=$('admin-pixels');c.width=image.width;c.height=image.height;c.getContext('2d').putImageData(image.data,0,0);}
$('admin-undo').addEventListener('click',()=>{if(pixelUndo.length){pixelRedo.push(pixelSnapshot());restorePixels(pixelUndo.pop());}});$('admin-redo').addEventListener('click',()=>{if(pixelRedo.length){pixelUndo.push(pixelSnapshot());restorePixels(pixelRedo.pop());}});
function wearablePixelAllowed(type,x,y){const uv=(sx,sy,w,h,d)=>y>=sy&&y<sy+d&&x>=sx+d&&x<sx+d+w*2||y>=sy+d&&y<sy+d+h&&x>=sx&&x<sx+2*d+2*w;if(type==='Hat')return uv(32,0,8,8,8);const body=uv(16,32,8,12,4)||uv(40,32,4,12,4)||uv(48,48,4,12,4);return type==='Trinket'?body:type==='Dress'&&(body||uv(0,32,4,12,4)||uv(0,48,4,12,4));}
fillGlassSettings();
